INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", "お！\nあそこに困ってそうな人発見！", "春咲 ひより", 1001, 0, 1, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "みんなみたいに\nわたしも強くならなきゃ", "大切な人を\n守れるようになりたい…って", "草野 優衣", 1002, 0, 1, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "フェンシングを始めてみては？", "キミに必要な集中力と感性が", "士条 怜", 1003, 0, 1, 1, "少しは磨かれると思いますよ。", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ねぇ、にいちゃん！", "今日はなにして遊ぶ？", "穂高 みそぎ", 1004, 0, 1, 1, "みそぎはねぇ、\nかくれんぼやりたい！", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "風宮あかりです", "ねぇ…", "風宮 あかり", 1006, 0, 1, 1, "私といっしょに…\nいかない？", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "出雲宮子なのー", "プリンたべたいのー", "出雲 宮子", 1007, 0, 1, 1, "食べ物の恨みは怖いのー", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ボクは虹村雪。", "キミもボクの美貌に\n吸い寄せられたんだね。", "虹村 雪", 1008, 0, 1, 1, "いいよ。\n見られることは運命さ…", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "フッ…聞いて後悔するがいい！", "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", "柊杏奈", 1009, 0, 1, 1, "人呼んで「疾風の冥姫」!!", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "マホマホ王国のプリンセス、\nまほ姫どす", "うさぎさん、\n運命の王子はんに巡りあわせてくれて", "姫宮 真歩", 1010, 0, 1, 1, "ほんまおおきにやわ～♪", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "衣之咲璃乃です！", "生き別れたお兄ちゃんを探して\n三千世界！", "衣之咲 璃乃", 1011, 0, 1, 1, "ここで会ったが\n100年目～！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "私はハツネ、\n結構強いんだよ。\nきらーん☆", "ち、超能力って…\n何のことかな～？", "柏崎 初音", 1012, 0, 1, 1, "…って、お願い！\n誰にも言わないでおいて～！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ちょす！\n美波鈴奈だよ～♪", "一応カリスマ読モJKやってまっす！", "美波 鈴奈", 1016, 0, 1, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "はいたーい。\n喜屋武香織さー。", "東京は遊園地みたいなところさー", "喜屋武 香織", 1017, 0, 1, 1, "でも、沖縄もとってもいいとこさー", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "支倉伊緒です。", "先生って呼ばれるのは\nくすぐったいから", "支倉 伊緒", 1018, 0, 1, 1, "イオちゃんって呼んでね。", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", "あ！/\お兄ちゃ～ん\nまってよ～", "茜 ミミ", 1020, 0, 1, 1, "ミミをおいてかないでぇ～", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "あ…あの…えっと…\n栗…林…くるみ…です……", "あの……\nふぇ……", "栗林 くるみ", 1021, 0, 1, 1, "ふぇぇぇぇぇん……", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "風宮よりです。\nあああああ！", "こんな私に貴重な時間を\n割いていただき、", "風宮 より", 1022, 0, 1, 1, "なんてありがとうございます！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", "おにいちゃんどこいくの？\nえ？", "北条 綾音", 1023, 0, 1, 1, "私こっち行きたいー\nね、早く早くー", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "わっ…わっ…私、\n天野すずめといいます！", "ふ、不束者ですが\nどうぞ末永く…って、", "天野 すずめ", 1025, 0, 1, 1, "これて何か違う…\nあああすみません！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "……クスクス…私は\n…倉石恵理子……", "あなたは…運命の……\n伴侶……", "倉石 恵理子", 1027, 0, 1, 1, "離しませんわ………\n絶対に…!!", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", "佐々木 咲恋", 1028, 0, 1, 1, "…そうでしょ？？", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "桜井望だよ！\nよろしくねっ", "ぇっと…\nキミ、私のこと知らないの?!", "桜井 望", 1029, 0, 1, 1, "あはは、\n私もまだまだだなぁ～", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "デケデケデンっ！", "初めまして、\n私はニノン・ジュベール申すデス！", "ニノン・ジュベール", 1030, 0, 1, 1, "ショーグン、\nワタシと一緒に天下統一デース！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "上喜しのぶです。\n手元のドクロが父です。", "でもって私の隣にいるのが……\nえ、見えない？", "上喜 しのぶ", 1031, 0, 1, 1, "おかしいですね……", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "目指すはビッグな\nお笑い芸人だっぺ！", "けんども\nそれには足りないモンが…", "野戸まひる", 1033, 0, 1, 1, "そう、\nオラのボケに突っ込める相方が…！", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", "ちょっと緊張しちゃって…", "綾瀬 ゆかり", 1034, 0, 1, 1, "ちょ\nちょっと一杯飲んできます…！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "氷川鏡華…です", "知らない人とは話しちゃいけないので", "氷川 鏡華", 1036, 0, 1, 1, "これ以上お話しすることは…\nないです！", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "柏崎…栞です。", "……あ、アラーム。", "柏崎 栞", 1038, 0, 1, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "ふ、双葉碧です。", "私、一人も友達がいなくて……", "双葉 碧", 1040, 0, 1, 1, "野に咲く花が、\n唯一の話相手です。", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "三角千歌です。", "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", "三角 千歌", 1042, 0, 1, 1, "そう思っています。", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "安芸真琴だ。", "あぁ？\nお前のそいつの仲間か？", "安芸 真琴", 1043, 0, 1, 1, "う、疑ってすまなかったな…", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "わらわこそは夜を総べる者！", "生けとし生ける全ての者よ！", "イリヤ・オーンスタイン", 1044, 0, 1, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "そこで騎士は妖精を乱暴に……", "ぐふふふふ……はっ！", "遠見 空花", 1045, 0, 1, 1, "ｌク、クウカに何かご用ですか!?", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "宮坂たまきにゃ♪\n猫はいいにゃよ？", "自由気ままで♪\n寝て遊んで、食べてケンカして…", "宮坂たまき", 1046, 0, 1, 1, "う～ん…\n猫ってホントに最高にゃ～♪", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "大神美冬よ！", "それでは早速クエストに…", "大神 美冬", 1048, 0, 1, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "星野静流だよ！", "クエストもバトルも\n掃除も洗濯も", "星野静流", 1049, 0, 1, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "アタシは玉泉美咲。", "見ての通りの\nセクシー美少女で", "玉泉美咲", 1050, 0, 1, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "？？？", "？？？？", "リマ", 1052, 0, 1, 1, "？？？？", 1.4, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィント", 1053, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", "ペコリーヌ", 1058, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", "コッコロ", 1059, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1.5, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (0, 0, 0, 1, 2, "モニカ・ヴァイスヴィントだ。", "菓子でつろうなどと\n稚拙な策を……", "キャル", 1060, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 1.5, 0);
